custom_css:
/* ==========================================================
   MoodTube theme: Rain Roses  (theme format v2)
   Built around a photo (images.bg): roses behind rain glass.
   Palette taken from the picture: deep navy-teal, dusty rose,
   warm amber glow, the teal reflection line (progress track).
   Flow layout only, so it holds at any player size.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Inter:wght@400;500&display=swap');

@keyframes rr-spin { to { transform: rotate(360deg); } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --rr-cream:  #ece3d6;
    --rr-dim:    #a9b6c4;
    --rr-rose:   #c4638f;
    --rr-rose-l: #e08fb2;
    --rr-amber:  #f0cf92;
    --rr-teal:   #6fb9c0;
    --rr-glass:  rgba(255, 255, 255, 0.08);
    --rr-line:   rgba(255, 255, 255, 0.16);
    --mt-text: var(--rr-cream);
    --mt-text-dim: #93a3b5;
    --mt-text-on-accent: #ffffff;
}

/* ---------- Sliders ---------- */
.mt-progress {
    --mt-slider-track: linear-gradient(90deg, transparent, var(--rr-teal) 12%, var(--rr-teal) 88%, transparent);
    --mt-slider-track-height: 2px;
    --mt-slider-track-radius: 1px;
    --mt-slider-thumb-size: 12px;
    --mt-slider-thumb-bg: var(--rr-amber);
    --mt-slider-thumb-bg-hover: #ffe3b0;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: 0 0 10px 2px rgba(240, 207, 146, 0.55);
    --mt-slider-progress: var(--rr-teal);
}
.mt-volume {
    --mt-slider-track: rgba(236, 227, 214, 0.3);
    --mt-slider-track-height: 2px;
    --mt-slider-track-radius: 1px;
    --mt-slider-thumb-size: 10px;
    --mt-slider-thumb-bg: var(--rr-cream);
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--rr-cream);
}

/* ---------- Shell ---------- */
.mt-player {
    container-type: size;
    padding: 38px 18px 16px;
    background: #0b1321;
    border: 1px solid var(--rr-line);
    border-radius: 24px;
    color: var(--rr-cream);
    font-family: 'Inter', 'Segoe UI', sans-serif;
    box-shadow: none;
    backdrop-filter: none; -webkit-backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

/* the photo is set in the "Фон плеера" slot; a veil keeps the controls readable */
.mt-slot-bg { background-position: center 40%; }
.mt-slot-scene { background-image: linear-gradient(180deg, rgba(8, 14, 26, 0.18) 0%, rgba(8, 14, 26, 0.3) 45%, rgba(8, 14, 26, 0.78) 100%); }

/* ---------- Header ---------- */
.mt-player-header { top: 14px; left: 22px; right: 96px; align-items: center; }
.mt-player-header-title { color: var(--rr-rose-l); font-size: 10px; font-weight: 500; letter-spacing: 0.22em; text-transform: uppercase; }
.mt-player-status { color: var(--rr-dim); opacity: 1; font-size: 10px; font-style: italic; letter-spacing: 0.04em; }
.mt-window-btn {
    top: 10px; width: 22px; height: 22px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 10px; color: var(--rr-cream);
    background: var(--rr-glass); border: 1px solid var(--rr-line); border-radius: 50%;
}
.mt-btn-search { right: 68px; }
.mt-btn-settings { right: 40px; }
.mt-btn-close { right: 12px; }
.mt-resize-handle i { color: rgba(236, 227, 214, 0.45); }

/* ---------- Cover ---------- */
.mt-player .mt-player-body { gap: 12px; }
.mt-cover {
    width: 104px; height: 104px; box-sizing: border-box;
    border: 1px solid rgba(240, 207, 146, 0.7); border-radius: 50%; background: #0b1321;
    box-shadow: 0 0 26px rgba(232, 194, 122, 0.35);
}
.mt-cover-img { background: #14203a; }
.mt-cover-hole { width: 12px; height: 12px; background: #0b1321; border: 1px solid rgba(240, 207, 146, 0.8); }
.mt-player.mt-is-playing .mt-cover-img { animation: rr-spin 14s linear infinite; }

/* ---------- Track ---------- */
.mt-track-title {
    color: var(--rr-cream); font-family: 'Cormorant Garamond', Georgia, serif;
    font-size: 19px; font-weight: 600; font-style: italic; letter-spacing: 0.01em; margin-bottom: 1px;
}
.mt-track-subtitle { color: var(--rr-rose-l); font-size: 10px; font-weight: 500; letter-spacing: 0.2em; text-transform: uppercase; }
.mt-btn-favorite { color: var(--rr-rose-l); font-size: 14px; }

/* ---------- Progress ---------- */
.mt-progress { margin-top: 0; }
.mt-time { color: var(--rr-dim); font-size: 10px; letter-spacing: 0.04em; }

/* ---------- Buttons: frosted glass strip ---------- */
.mt-controls {
    gap: 10px; padding: 6px 12px; border-radius: 24px;
    background: var(--rr-glass); border: 1px solid var(--rr-line);
    backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
}
.mt-controls > .mt-btn {
    width: 30px; height: 30px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 12px; color: var(--rr-cream); background: transparent; border: 1px solid transparent; border-radius: 50%;
}
.mt-controls > .mt-btn-play {
    width: 42px; height: 42px; font-size: 15px; color: var(--rr-amber);
    background: rgba(240, 207, 146, 0.12); border: 1px solid rgba(240, 207, 146, 0.7);
}
.mt-controls > .mt-btn:hover { transform: none; color: var(--rr-rose-l); background: rgba(255, 255, 255, 0.08); }
.mt-controls > .mt-btn-play:hover { color: #ffe3b0; background: rgba(240, 207, 146, 0.22); }
.mt-btn-ai.mt-is-busy { color: var(--rr-rose-l); }

.mt-volume-icon { color: var(--rr-dim); font-size: 11px; }

/* wide bar: tighter parts so everything fits in one row */
.mt-player.moodtube-row-layout .mt-player-body { gap: 8px; }
.mt-player.moodtube-row-layout .mt-cover { box-shadow: 0 0 14px rgba(232, 194, 122, 0.3); }
.mt-player.moodtube-row-layout .mt-track-info { flex: 1 1 110px; min-width: 64px; padding-right: 20px; }
.mt-player.moodtube-row-layout .mt-track-title { font-size: 15px; }
.mt-player.moodtube-row-layout .mt-track-subtitle { font-size: 8px; letter-spacing: 0.14em; }
.mt-player.moodtube-row-layout .mt-progress { flex: 1 1 80px; min-width: 60px; }
.mt-player.moodtube-row-layout .mt-controls { gap: 2px; padding: 3px 6px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn { width: 26px; height: 26px; font-size: 11px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play { width: 34px; height: 34px; font-size: 13px; }
.mt-player.moodtube-row-layout .mt-volume { flex: 0 1 80px; min-width: 56px; }

/* ---------- Queue / playlists ---------- */
.mt-panel {
    background: rgba(8, 14, 26, 0.9); padding-top: 42px; border-radius: inherit;
    backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
}
.mt-panel-title { color: var(--rr-rose-l); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--rr-cream); }
.mt-queue-item { background: var(--rr-glass); border-color: transparent; border-radius: 12px; }
.mt-queue-item:hover { background: rgba(255, 255, 255, 0.14); }
.mt-queue-item.mt-is-current { background: rgba(196, 99, 143, 0.18); border-color: var(--rr-rose); }
.mt-queue-thumb { border-radius: 50%; }
.mt-queue-thumb.mt-is-empty { background: rgba(255, 255, 255, 0.12); }
.mt-queue-title { color: var(--rr-dim); }
.mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: var(--rr-cream); }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #e57b86; }
.mt-queue-now, .mt-queue-add { color: var(--rr-amber); }
.mt-queue-dislike { background-color: var(--rr-rose-l); }
.mt-queue-empty { color: var(--rr-dim); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
    background: rgba(11, 19, 33, 0.78); border-color: rgba(240, 207, 146, 0.7);
    box-shadow: 0 0 14px rgba(232, 194, 122, 0.3); color: var(--rr-amber);
}

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: rgba(196, 99, 143, 0.7) transparent; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 6px; height: 6px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: transparent; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: rgba(196, 99, 143, 0.7); border-radius: 3px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(4, 8, 16, 0.6);
    --mt-modal-shadow: none;
    --mt-text-strong: #ffffff;
    --mt-divider: rgba(255, 255, 255, 0.1);
}
#mt-settings-modal .mt-flex-container { border: 1px solid var(--rr-line); border-radius: 24px; }
#mt-settings-modal .mt-header h3 { font-family: 'Cormorant Garamond', Georgia, serif; font-size: 1.35em; font-style: italic; }
#mt-settings-modal .mt-close { color: var(--rr-cream); }
#mt-settings-modal .mt-tag { background-color: var(--rr-glass); border-color: var(--rr-line); box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: rgba(255, 255, 255, 0.14); border-color: var(--rr-rose);
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--rr-rose); border-color: var(--rr-rose); box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: var(--rr-glass); border-color: var(--rr-line); }
#mt-settings-modal .mt-btn-test:hover { background: rgba(255, 255, 255, 0.14); border-color: var(--rr-rose); }
#mt-settings-modal .mt-subpanel { background: rgba(255, 255, 255, 0.05); }

/* ---------- Search panel and playlists (added to the extension later) ---------- */

.mt-panel-search { --mt-bg-primary: #0b1321; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #fff) !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--rr-rose); --mt-pl-spotify-tab-text: #ffffff; }
.mt-btn-favorite.mt-is-active { color: var(--rr-rose-l); }
.mt-pl-tabs { background: var(--rr-glass); border: 1px solid var(--rr-line); }
.mt-pl-tool { background: var(--rr-glass); border-color: var(--rr-line); color: var(--rr-cream); }
.mt-pl-tool:hover { background: rgba(255, 255, 255, 0.14); }
.mt-pl-tool.mt-pl-play { background: var(--rr-rose); border-color: var(--rr-rose); color: #ffffff; }
.mt-pl-inline-cancel { background: var(--rr-glass); color: var(--rr-cream); }
.mt-pl-cover-empty { background: rgba(255, 255, 255, 0.1); color: var(--rr-dim); }
.mt-pl-modal { --mt-overlay: rgba(4, 8, 16, 0.6); }
.mt-pl-modal-box { background: rgba(11, 19, 33, 0.96); border: 1px solid var(--rr-line); border-radius: 22px; box-shadow: none; }
.mt-pl-modal-track { border-bottom-color: var(--rr-line); }
.mt-pl-option { background: var(--rr-glass); }
.mt-pl-option:hover { background: rgba(255, 255, 255, 0.14); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--rr-amber); }

/* the header has less room now (search, settings, close): drop the status text in a narrow window */
@container (max-width: 300px) { .mt-player .mt-player-status { display: none; } }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-window-btn.mt-btn-lyrics { right: 96px; }
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 8px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 10px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 42px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 74px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 106px; left: auto; }
/* == /window buttons == */
